import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        long ans = 1;
        int[] vis = new int[(int) p];

        for (int i = 1 - (k == 1 ? 1 : 0); i < p; i++) {
            if (vis[i]) continue;
            int j = i;
            do {
                vis[j] = 1;
                j = (int)((j * k) % p);
            } while (i != j && j != 0);
            ans = (ans * p) % 1000000007;
        }
        System.out.println(ans);
    }
}
